cache_manager_script = '''#!/usr/bin/env python3
"""
OASIS v3 - Cache Manager
Ultra-lightweight local caching system for mobile optimization
"""

import json
import os
import time
import gzip
from datetime import datetime

class CacheManager:
    """Ultra-lightweight caching system with compression"""

    def __init__(self, home_dir, max_size_mb=50):
        self.cache_dir = os.path.join(home_dir, "cache")
        self.max_size_bytes = max_size_mb * 1024 * 1024
        self.index_file = os.path.join(self.cache_dir, "_index.json")

        os.makedirs(self.cache_dir, exist_ok=True)
        self.index = self.load_index()

    def load_index(self):
        """Load cache index"""
        try:
            if os.path.exists(self.index_file):
                with open(self.index_file, 'r') as f:
                    return json.load(f)
        except Exception:
            pass
        return {}

    def save_index(self):
        """Save cache index"""
        try:
            with open(self.index_file, 'w') as f:
                json.dump(self.index, f)
        except Exception:
            pass

    def get(self, key):
        """Get cached data with decompression"""
        try:
            if key not in self.index:
                return None

            entry = self.index[key]

            # Check expiry
            if entry.get("expires", 0) < time.time():
                self.delete(key)
                return None

            # Load compressed data
            cache_file = os.path.join(self.cache_dir, f"{key}.gz")
            if os.path.exists(cache_file):
                with gzip.open(cache_file, 'rt') as f:
                    data = json.load(f)

                # Update access time
                entry["last_accessed"] = time.time()
                self.save_index()

                return data

        except Exception:
            pass

        return None

    def set(self, key, value, ttl=3600):
        """Cache data with compression"""
        try:
            # Clean up if needed
            self.cleanup_if_needed()

            # Compress and save data
            cache_file = os.path.join(self.cache_dir, f"{key}.gz")
            with gzip.open(cache_file, 'wt') as f:
                json.dump(value, f)

            # Update index
            self.index[key] = {
                "created": time.time(),
                "expires": time.time() + ttl,
                "last_accessed": time.time(),
                "size": os.path.getsize(cache_file)
            }

            self.save_index()

        except Exception:
            pass

    def delete(self, key):
        """Delete cached item"""
        try:
            cache_file = os.path.join(self.cache_dir, f"{key}.gz")
            if os.path.exists(cache_file):
                os.remove(cache_file)

            if key in self.index:
                del self.index[key]
                self.save_index()

        except Exception:
            pass

    def cleanup_if_needed(self):
        """Cleanup old cache entries if size limit exceeded"""
        try:
            total_size = sum(entry.get("size", 0) for entry in self.index.values())

            if total_size > self.max_size_bytes:
                # Sort by last accessed time (oldest first)
                sorted_keys = sorted(
                    self.index.keys(),
                    key=lambda k: self.index[k].get("last_accessed", 0)
                )

                # Delete oldest entries until under limit
                for key in sorted_keys:
                    if total_size <= self.max_size_bytes * 0.8:  # 80% of limit
                        break

                    entry_size = self.index[key].get("size", 0)
                    self.delete(key)
                    total_size -= entry_size

        except Exception:
            pass

    def clear_expired(self):
        """Clear expired cache entries"""
        current_time = time.time()
        expired_keys = []

        for key, entry in self.index.items():
            if entry.get("expires", 0) < current_time:
                expired_keys.append(key)

        for key in expired_keys:
            self.delete(key)

    def get_stats(self):
        """Get cache statistics"""
        total_size = sum(entry.get("size", 0) for entry in self.index.values())
        total_items = len(self.index)

        return {
            "total_items": total_items,
            "total_size_mb": total_size / (1024 * 1024),
            "max_size_mb": self.max_size_bytes / (1024 * 1024),
            "usage_percent": (total_size / self.max_size_bytes) * 100 if self.max_size_bytes > 0 else 0
        }

class OfflineQueue:
    """Queue for requests when offline"""

    def __init__(self, home_dir):
        self.queue_dir = os.path.join(home_dir, "queue")
        self.queue_file = os.path.join(self.queue_dir, "pending.json")

        os.makedirs(self.queue_dir, exist_ok=True)
        self.queue = self.load_queue()

    def load_queue(self):
        """Load pending requests queue"""
        try:
            if os.path.exists(self.queue_file):
                with open(self.queue_file, 'r') as f:
                    return json.load(f)
        except Exception:
            pass
        return []

    def save_queue(self):
        """Save queue to disk"""
        try:
            with open(self.queue_file, 'w') as f:
                json.dump(self.queue, f, indent=2)
        except Exception:
            pass

    def add(self, request_data):
        """Add request to offline queue"""
        request_data["queued_at"] = time.time()
        request_data["id"] = f"req_{int(time.time() * 1000)}"

        self.queue.append(request_data)
        self.save_queue()

        return request_data["id"]

    def get_pending(self):
        """Get all pending requests"""
        return self.queue.copy()

    def remove(self, request_id):
        """Remove request from queue"""
        self.queue = [req for req in self.queue if req.get("id") != request_id]
        self.save_queue()

    def clear(self):
        """Clear all pending requests"""
        self.queue = []
        self.save_queue()
'''

