cache_manager_script = '''#!/usr/bin/env python3
"""
OASIS v3 Cache Manager - Ultra-Lightweight Caching System
Smart caching with gzip compression and TTL for mobile optimization
Using ONLY Python stdlib - perfect for Termux environment

Author: OASIS v3 Team
Target: <5MB footprint, offline-first mobile caching
"""

import os
import json
import time
import gzip
import pickle
import hashlib
from datetime import datetime, timedelta


class CacheManager:
    """Ultra-lightweight caching system for mobile AI requests"""

    def __init__(self, config):
        """Initialize cache manager with mobile-optimized settings"""
        self.config = config
        self.cache_dir = os.path.expanduser("~/oasis_v3/cache")
        self.offline_queue_path = os.path.join(self.cache_dir, "offline_queue.json")

        # Cache settings
        self.default_ttl = config.get("cache_ttl", 3600)  # 1 hour default
        self.max_cache_size = self._parse_size(config.get("max_cache_size", "10MB"))
        self.compression_enabled = True  # Always compress for mobile

        # Statistics for mobile UI
        self.stats = {
            "hits": 0,
            "misses": 0,
            "size": 0,
            "files": 0
        }

        # Offline queue for when network is unavailable
        self.offline_queue = []

        # Create cache directory
        os.makedirs(self.cache_dir, exist_ok=True)
        self._load_offline_queue()
        self._update_stats()

        print(f"💾 Cache initialized: {self.cache_dir}")
        print(f"📦 Max size: {self._format_size(self.max_cache_size)}")

    def _parse_size(self, size_str):
        """Parse size string like '10MB' to bytes"""
        if isinstance(size_str, int):
            return size_str

        size_str = size_str.upper()
        if size_str.endswith('MB'):
            return int(size_str[:-2]) * 1024 * 1024
        elif size_str.endswith('KB'):
            return int(size_str[:-2]) * 1024
        elif size_str.endswith('GB'):
            return int(size_str[:-2]) * 1024 * 1024 * 1024
        else:
            return int(size_str)

    def _format_size(self, size_bytes):
        """Format bytes to human-readable string"""
        if size_bytes < 1024:
            return f"{size_bytes}B"
        elif size_bytes < 1024 * 1024:
            return f"{size_bytes / 1024:.1f}KB"
        else:
            return f"{size_bytes / (1024 * 1024):.1f}MB"

    def _get_cache_key_hash(self, key):
        """Generate safe filename from cache key"""
        return hashlib.md5(key.encode()).hexdigest()

    def _get_cache_path(self, key):
        """Get file path for cache key"""
        key_hash = self._get_cache_key_hash(key)
        return os.path.join(self.cache_dir, f"{key_hash}.cache")

    def _get_metadata_path(self, key):
        """Get metadata file path for cache key"""
        key_hash = self._get_cache_key_hash(key)
        return os.path.join(self.cache_dir, f"{key_hash}.meta")

    def set(self, key, value, ttl=None):
        """Set cache value with TTL and compression"""
        try:
            if ttl is None:
                ttl = self.default_ttl

            cache_path = self._get_cache_path(key)
            meta_path = self._get_metadata_path(key)

            # Prepare metadata
            metadata = {
                "key": key,
                "created": time.time(),
                "ttl": ttl,
                "expires": time.time() + ttl,
                "compressed": self.compression_enabled,
                "size": len(str(value))
            }

            # Save compressed data
            if self.compression_enabled:
                with gzip.open(cache_path, 'wt', encoding='utf-8') as f:
                    if isinstance(value, (dict, list)):
                        json.dump(value, f)
                    else:
                        f.write(str(value))
            else:
                with open(cache_path, 'w', encoding='utf-8') as f:
                    if isinstance(value, (dict, list)):
                        json.dump(value, f)
                    else:
                        f.write(str(value))

            # Save metadata
            with open(meta_path, 'w') as f:
                json.dump(metadata, f)

            # Check cache size limits
            self._enforce_size_limit()
            self._update_stats()

            return True

        except Exception as e:
            print(f"❌ Cache set error: {e}")
            return False

    def get(self, key):
        """Get cached value with TTL check"""
        try:
            cache_path = self._get_cache_path(key)
            meta_path = self._get_metadata_path(key)

            # Check if files exist
            if not os.path.exists(cache_path) or not os.path.exists(meta_path):
                self.stats["misses"] += 1
                return None

            # Load metadata and check TTL
            with open(meta_path, 'r') as f:
                metadata = json.load(f)

            if time.time() > metadata.get("expires", 0):
                # Expired, remove files
                self._remove_cache_files(key)
                self.stats["misses"] += 1
                return None

            # Load cached data
            if metadata.get("compressed", False):
                with gzip.open(cache_path, 'rt', encoding='utf-8') as f:
                    try:
                        data = json.load(f)
                    except json.JSONDecodeError:
                        f.seek(0)
                        data = f.read()
            else:
                with open(cache_path, 'r', encoding='utf-8') as f:
                    try:
                        data = json.load(f)
                    except json.JSONDecodeError:
                        f.seek(0)
                        data = f.read()

            self.stats["hits"] += 1
            return data

        except Exception as e:
            print(f"❌ Cache get error: {e}")
            self.stats["misses"] += 1
            return None

    def _remove_cache_files(self, key):
        """Remove cache and metadata files for key"""
        try:
            cache_path = self._get_cache_path(key)
            meta_path = self._get_metadata_path(key)

            if os.path.exists(cache_path):
                os.remove(cache_path)
            if os.path.exists(meta_path):
                os.remove(meta_path)

        except Exception as e:
            print(f"⚠️  Error removing cache files: {e}")

    def cleanup_expired(self):
        """Remove expired cache entries"""
        removed_count = 0
        current_time = time.time()

        try:
            for filename in os.listdir(self.cache_dir):
                if filename.endswith('.meta'):
                    meta_path = os.path.join(self.cache_dir, filename)

                    try:
                        with open(meta_path, 'r') as f:
                            metadata = json.load(f)

                        if current_time > metadata.get("expires", 0):
                            key = metadata.get("key", "")
                            if key:
                                self._remove_cache_files(key)
                                removed_count += 1
                    except Exception:
                        continue

            if removed_count > 0:
                print(f"🧹 Cleaned up {removed_count} expired cache entries")
                self._update_stats()

        except Exception as e:
            print(f"❌ Cleanup error: {e}")

    def _enforce_size_limit(self):
        """Enforce cache size limit by removing oldest entries"""
        try:
            current_size = self._calculate_cache_size()

            if current_size <= self.max_cache_size:
                return

            # Get all cache files with metadata
            cache_files = []
            for filename in os.listdir(self.cache_dir):
                if filename.endswith('.meta'):
                    meta_path = os.path.join(self.cache_dir, filename)
                    try:
                        with open(meta_path, 'r') as f:
                            metadata = json.load(f)
                        cache_files.append((metadata.get("created", 0), metadata.get("key", "")))
                    except Exception:
                        continue

            # Sort by creation time (oldest first)
            cache_files.sort(key=lambda x: x[0])

            # Remove oldest entries until under size limit
            removed_count = 0
            for _, key in cache_files:
                if key:
                    self._remove_cache_files(key)
                    removed_count += 1

                    if self._calculate_cache_size() <= self.max_cache_size:
                        break

            if removed_count > 0:
                print(f"📦 Removed {removed_count} cache entries to enforce size limit")

        except Exception as e:
            print(f"❌ Size limit enforcement error: {e}")

    def _calculate_cache_size(self):
        """Calculate total cache size in bytes"""
        total_size = 0
        try:
            for filename in os.listdir(self.cache_dir):
                file_path = os.path.join(self.cache_dir, filename)
                if os.path.isfile(file_path):
                    total_size += os.path.getsize(file_path)
        except Exception:
            pass
        return total_size

    def _update_stats(self):
        """Update cache statistics"""
        try:
            self.stats["size"] = self._calculate_cache_size()
            self.stats["files"] = len([f for f in os.listdir(self.cache_dir) 
                                     if f.endswith('.cache')])
        except Exception:
            pass

    def get_size(self):
        """Get formatted cache size for mobile UI"""
        self._update_stats()
        return self._format_size(self.stats["size"])

    def get_stats(self):
        """Get cache statistics for monitoring"""
        self._update_stats()
        return self.stats.copy()

    def clear_all(self):
        """Clear all cache entries"""
        try:
            for filename in os.listdir(self.cache_dir):
                if filename.endswith(('.cache', '.meta')):
                    os.remove(os.path.join(self.cache_dir, filename))

            self.stats = {"hits": 0, "misses": 0, "size": 0, "files": 0}
            print("🧹 All cache entries cleared")

        except Exception as e:
            print(f"❌ Cache clear error: {e}")

    # Offline Queue Management for Mobile Networks
    def _load_offline_queue(self):
        """Load offline queue from disk"""
        try:
            if os.path.exists(self.offline_queue_path):
                with open(self.offline_queue_path, 'r') as f:
                    self.offline_queue = json.load(f)
        except Exception as e:
            print(f"⚠️  Offline queue load error: {e}")
            self.offline_queue = []

    def _save_offline_queue(self):
        """Save offline queue to disk"""
        try:
            with open(self.offline_queue_path, 'w') as f:
                json.dump(self.offline_queue, f, indent=2)
        except Exception as e:
            print(f"❌ Offline queue save error: {e}")

    def add_to_offline_queue(self, request_type, data):
        """Add request to offline queue when network unavailable"""
        try:
            offline_request = {
                "id": hashlib.md5(f"{request_type}_{str(data)}_{time.time()}".encode()).hexdigest(),
                "request_type": request_type,
                "data": data,
                "timestamp": time.time(),
                "retries": 0
            }

            self.offline_queue.append(offline_request)
            self._save_offline_queue()

            print(f"📱 Added to offline queue: {request_type}")
            return offline_request["id"]

        except Exception as e:
            print(f"❌ Offline queue add error: {e}")
            return None

    def get_offline_queue(self):
        """Get pending offline requests"""
        return self.offline_queue.copy()

    def remove_from_offline_queue(self, request_id):
        """Remove processed request from offline queue"""
        try:
            self.offline_queue = [req for req in self.offline_queue 
                                if req.get("id") != request_id]
            self._save_offline_queue()
            return True
        except Exception as e:
            print(f"❌ Offline queue remove error: {e}")
            return False

    def clear_offline_queue(self):
        """Clear all offline queue entries"""
        try:
            self.offline_queue = []
            self._save_offline_queue()
